#!/usr/bin/env python3
"""Writes src/blink_breaks.rs from the pair table tools/chromium/pairs.html measured:

    tools/chromium/run.sh empty.json pairs.json --page pairs.html     (empty.json is `{}`)
    tools/gen-blink-breaks.py pairs.json > src/blink_breaks.rs
"""
import json
import sys

pairs = json.load(open(sys.argv[1]))
print("""//! @generated by tools/gen-blink-breaks.py from Chromium's own answers (Electron 33,
//! `tools/chromium/pairs.html`). Do not edit.
//!
//! Blink does not run UAX #14 on ASCII: between two printable ASCII characters its line
//! breaker looks a table up (`kAsciiLineBreakTable`, kept for compatibility with other
//! browsers: it breaks after `?` and before `(` but not after `/`), and `word-break:
//! break-all` adds pairs from a second table. Row = the character before the break
//! (`'!'` is row 0), bit = the character after it (`'!'` is bit 0).
""")
for name, const in (("normal", "NORMAL"), ("break_all", "BREAK_ALL")):
    rows = pairs[name]
    assert len(rows) == 94 and all(len(row) == 94 for row in rows)
    print(f"pub(crate) const {const}: [u128; 94] = [")
    for row in rows:
        value = sum(1 << bit for bit, flag in enumerate(row) if flag == "1")
        print(f"    0x{value:024x},")
    print("];\n")
